-- ============================================================
-- Atomic claim submission.
-- PostgREST cannot wrap multiple writes in one transaction, so a claim's rows
-- were previously written across several client calls (claim, line items,
-- adjudications, reasons, accumulators, history) — a mid-write failure could
-- leave partial state. This function performs the entire submission write in a
-- single transaction and is called from the repository via client.rpc().
--
-- SECURITY INVOKER: runs as the caller (the server-side service role, which
-- bypasses RLS). search_path is pinned and every object is schema-qualified.
-- EXECUTE is revoked from anon/authenticated so it is not on the public surface.
-- ============================================================
create or replace function public.submit_claim_atomic(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_claim_id     uuid;
  v_policy_id    uuid;
  v_line         jsonb;
  v_line_id      uuid;
  v_adj_id       uuid;
  v_reason       jsonb;
  v_period_start date;
  v_period_end   date;
  v_usage        jsonb;
begin
  v_policy_id := (payload->'claim'->>'policy_id')::uuid;

  insert into public.claim (claim_number, policy_id, status, provider_name,
                            provider_identifier, total_billed_amount, total_payable_amount)
  values (payload->'claim'->>'claim_number', v_policy_id, payload->'claim'->>'status',
          payload->'claim'->>'provider_name', payload->'claim'->>'provider_identifier',
          (payload->'claim'->>'total_billed_amount')::numeric,
          (payload->'claim'->>'total_payable_amount')::numeric)
  returning id into v_claim_id;

  insert into public.claim_status_history (claim_id, from_status, to_status, reason, changed_by)
  values (v_claim_id, null, payload->'claim'->>'status', 'submission', 'system');

  for v_line in select * from jsonb_array_elements(payload->'lines')
  loop
    insert into public.claim_line_item (claim_id, line_number, service_type_id, service_date,
                                        billed_amount, quantity, diagnosis_code, status)
    values (v_claim_id, (v_line->>'line_number')::int, (v_line->>'service_type_id')::uuid,
            (v_line->>'service_date')::date, (v_line->>'billed_amount')::numeric,
            (v_line->>'quantity')::int, v_line->>'diagnosis_code', v_line->>'decision')
    returning id into v_line_id;

    insert into public.adjudication (line_item_id, sequence, is_current, decision, covered_amount,
                                     deductible_applied, copay_amount, coinsurance_amount,
                                     payable_amount, triggered_by)
    values (v_line_id, 1, true, v_line->>'decision', (v_line->>'covered_amount')::numeric,
            (v_line->>'deductible_applied')::numeric, (v_line->>'copay_amount')::numeric,
            (v_line->>'coinsurance_amount')::numeric, (v_line->>'payable_amount')::numeric, 'submission')
    returning id into v_adj_id;

    for v_reason in select * from jsonb_array_elements(coalesce(v_line->'reasons', '[]'::jsonb))
    loop
      insert into public.adjudication_reason (adjudication_id, reason_code_id, message)
      select v_adj_id, rc.id, coalesce(v_reason->>'message', '')
      from public.reason_code rc
      where rc.code = v_reason->>'code';
    end loop;

    insert into public.line_item_status_history (line_item_id, from_status, to_status, reason, changed_by)
    values (v_line_id, 'pending', v_line->>'decision', 'submission', 'system');
  end loop;

  v_period_start := (payload->'accumulators'->>'period_start')::date;
  v_period_end   := (payload->'accumulators'->>'period_end')::date;

  insert into public.accumulator (policy_id, service_type_id, period_start, period_end, deductible_met_amount)
  values (v_policy_id, null, v_period_start, v_period_end,
          (payload->'accumulators'->>'deductible_met')::numeric)
  on conflict (policy_id, period_start) where service_type_id is null
  do update set deductible_met_amount = excluded.deductible_met_amount;

  for v_usage in select * from jsonb_array_elements(coalesce(payload->'accumulators'->'usage', '[]'::jsonb))
  loop
    insert into public.accumulator (policy_id, service_type_id, period_start, period_end, amount_used, visits_used)
    values (v_policy_id, (v_usage->>'service_type_id')::uuid, v_period_start, v_period_end,
            (v_usage->>'amount_used')::numeric, (v_usage->>'visits_used')::int)
    on conflict (policy_id, service_type_id, period_start) where service_type_id is not null
    do update set amount_used = excluded.amount_used, visits_used = excluded.visits_used;
  end loop;

  return v_claim_id;
end;
$$;

revoke execute on function public.submit_claim_atomic(jsonb) from public, anon, authenticated;
grant execute on function public.submit_claim_atomic(jsonb) to service_role;

"""FastAPI interface — the thin demo layer over the adjudication engine.

Endpoints exercise the whole system end-to-end:
  POST /claims                      submit a claim with line items and adjudicate it
  GET  /claims/{id}                 retrieve a persisted, adjudicated claim
  POST /claims/{id}/disputes        open a dispute on a line of a claim
  POST /disputes/{id}/resolve       resolve a dispute -> re-adjudicate the line
  POST /claims/{id}/lines/{id}/review  complete manual review of a needs_review line
"""
from uuid import UUID

from fastapi import Depends, FastAPI, HTTPException

from app import claims_service as svc
from app.claims_repository import ClaimRepository, SupabaseClaimRepository
from app.db import get_supabase
from app.schemas import ClaimIn, ClaimOut, DisputeIn, DisputeOut, ReviewIn

app = FastAPI(title="Claims Processing System", version="1.0.0")


def get_repository() -> ClaimRepository:
    """Inject the live repository; overridden with a fake in tests."""
    return SupabaseClaimRepository(get_supabase())


@app.get("/health")
def health_check():
    return {"status": "ok"}


@app.post("/claims", response_model=ClaimOut, status_code=201)
def submit_claim(payload: ClaimIn, repo: ClaimRepository = Depends(get_repository)):
    try:
        return svc.submit_claim(repo, payload)
    except svc.PolicyNotFound:
        raise HTTPException(status_code=404, detail="Policy not found.")
    except svc.UnknownServiceType as exc:
        raise HTTPException(status_code=422, detail=f"Unknown service type: {exc.code}")


@app.get("/claims/{claim_id}", response_model=ClaimOut)
def get_claim(claim_id: UUID, repo: ClaimRepository = Depends(get_repository)):
    try:
        return svc.get_claim(repo, str(claim_id))
    except svc.ClaimNotFound:
        raise HTTPException(status_code=404, detail="Claim not found.")


@app.post("/claims/{claim_id}/disputes", response_model=DisputeOut, status_code=201)
def open_dispute(claim_id: UUID, payload: DisputeIn, repo: ClaimRepository = Depends(get_repository)):
    try:
        return svc.open_dispute(repo, str(claim_id), payload)
    except svc.ClaimNotFound:
        raise HTTPException(status_code=404, detail="Claim not found.")
    except svc.LineNotInClaim:
        raise HTTPException(status_code=422, detail="line_item_id does not belong to this claim.")


@app.post("/disputes/{dispute_id}/resolve", response_model=ClaimOut)
def resolve_dispute(dispute_id: UUID, repo: ClaimRepository = Depends(get_repository)):
    try:
        return svc.resolve_dispute(repo, str(dispute_id))
    except svc.DisputeNotFound:
        raise HTTPException(status_code=404, detail="Dispute not found.")
    except svc.DisputeAlreadyResolved:
        raise HTTPException(status_code=409, detail="Dispute is already resolved.")
    except svc.LineNotInClaim:
        raise HTTPException(status_code=422, detail="Dispute is not resolvable (no target line item).")


@app.post("/claims/{claim_id}/lines/{line_id}/review", response_model=ClaimOut)
def complete_review(claim_id: UUID, line_id: UUID, payload: ReviewIn, repo: ClaimRepository = Depends(get_repository)):
    try:
        return svc.complete_review(repo, str(claim_id), str(line_id), payload.decision, payload.note)
    except svc.ClaimNotFound:
        raise HTTPException(status_code=404, detail="Claim not found.")
    except svc.LineNotInClaim:
        raise HTTPException(status_code=422, detail="line_id does not belong to this claim.")
    except svc.LineNotUnderReview:
        raise HTTPException(status_code=409, detail="Line item is not awaiting manual review.")

"""API tests for the claims + dispute endpoints, run fully offline.

A fake in-memory repository is injected via FastAPI's dependency override, so the
real adjudication engine runs but no database is touched.
"""
from datetime import date
from decimal import Decimal
import uuid

import pytest
from fastapi.testclient import TestClient

from app.claims_repository import PolicyContextData
from app.domain.models import CoverageRule, Plan, PolicyContext
from app.main import app, get_repository

POLICY_ID = "11111111-1111-1111-1111-111111111111"


def _dec(value) -> Decimal:
    return Decimal(str(value))


def make_context(deductible="0", rules=None) -> PolicyContextData:
    rules = rules if rules is not None else {
        "PHYSIO": CoverageRule(service_type_code="PHYSIO"),          # fully covered
        "DENTAL": CoverageRule(service_type_code="DENTAL", is_covered=False),  # not covered
    }
    return PolicyContextData(
        policy_id=POLICY_ID,
        plan=Plan(annual_deductible_amount=Decimal(deductible)),
        policy=PolicyContext(benefit_period_start=date(2026, 1, 1), benefit_period_end=date(2026, 12, 31)),
        rules=rules,
        service_type_ids={"PHYSIO": "st-physio", "DENTAL": "st-dental", "OPTICAL": "st-optical"},
    )


class FakeRepo:
    def __init__(self, context):
        self.context = context
        self._claims: dict = {}
        self._disputes: dict = {}
        self.saved_accumulators = None

    def load_policy_context(self, policy_id):
        return self.context if str(policy_id) == POLICY_ID else None

    def save_claim(self, saved, period_start, period_end, deductible_met, usage, service_type_ids):
        # Mirrors the atomic submit_claim_atomic RPC: persists the claim and
        # writes accumulators in one call.
        claim_id = str(uuid.uuid4())
        for line in saved.lines:
            line.line_id, line.current_sequence = str(uuid.uuid4()), 1
        self._claims[claim_id] = saved
        self.saved_accumulators = {"deductible_met": deductible_met, "usage": dict(usage)}
        return claim_id

    def save_accumulators(self, policy_id, ps, pe, deductible_met, usage, service_type_ids):
        self.saved_accumulators = {"deductible_met": deductible_met, "usage": dict(usage)}

    def get_claim(self, claim_id):
        return self._claims.get(str(claim_id))

    def create_dispute(self, claim_id, line_item_id, reason):
        if str(claim_id) not in self._claims:
            return None
        did = str(uuid.uuid4())
        self._disputes[did] = {"id": did, "claim_id": str(claim_id), "line_item_id": line_item_id,
                               "reason": reason, "status": "open", "resolution_outcome": None}
        self._claims[str(claim_id)].status = "disputed"
        return self._disputes[did]

    def get_dispute(self, dispute_id):
        return self._disputes.get(str(dispute_id))

    def apply_resolution(self, *, dispute_id, claim_id, line_id, prev_sequence, new_line,
                         new_claim_status, new_total, outcome, deductible_met, usage, **_):
        claim = self._claims[str(claim_id)]
        for line in claim.lines:
            if line.line_id == line_id:
                line.decision, line.reasons = new_line.decision, new_line.reasons
                line.covered_amount, line.payable_amount = new_line.covered_amount, new_line.payable_amount
                line.deductible_applied = new_line.deductible_applied
                line.copay_amount, line.coinsurance_amount = new_line.copay_amount, new_line.coinsurance_amount
                line.current_sequence = prev_sequence + 1
        claim.status, claim.total_payable_amount = new_claim_status, new_total
        self._disputes[str(dispute_id)].update(status="resolved", resolution_outcome=outcome)
        self.saved_accumulators = {"deductible_met": deductible_met, "usage": dict(usage)}

    def apply_review(self, *, claim_id, line_id, prev_sequence, new_line,
                     new_claim_status, new_total, deductible_met, usage, **_):
        claim = self._claims[str(claim_id)]
        for line in claim.lines:
            if line.line_id == line_id:
                line.decision, line.reasons = new_line.decision, new_line.reasons
                line.covered_amount, line.payable_amount = new_line.covered_amount, new_line.payable_amount
                line.deductible_applied = new_line.deductible_applied
                line.copay_amount, line.coinsurance_amount = new_line.copay_amount, new_line.coinsurance_amount
                line.current_sequence = prev_sequence + 1
        claim.status, claim.total_payable_amount = new_claim_status, new_total
        self.saved_accumulators = {"deductible_met": deductible_met, "usage": dict(usage)}


@pytest.fixture
def make_client():
    def _make(context=None):
        repo = FakeRepo(context or make_context())
        app.dependency_overrides[get_repository] = lambda: repo
        return TestClient(app), repo
